def compute(vars):
    ending_balance_2017 = vars["v1"]
    ending_balance_2018 = vars["v2"]

    if ending_balance_2017 == 0:
        return None

    change = ending_balance_2018 - ending_balance_2017
    percentage_change = (change / ending_balance_2017) * 100

    return {
        "value": percentage_change,
        "trace": {
            "ending_balance_2017": ending_balance_2017,
            "ending_balance_2018": ending_balance_2018,
            "change": change,
            "percentage_change": percentage_change,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
